     1|// VitaHero Neon DB Backend — Cloudflare Worker
     2|// Connects to Neon Postgres (vita_hero schema) for all CRUD operations.
     3|// Handles Google Sign-In, phone OTP via Twilio, and session-token auth.
     4|
     5|import { neon } from "@neondatabase/serverless";
     6|
     7|const SCHEMA = "vita_hero";
     8|const GOOGLE_TOKENINFO = "https://oauth2.googleapis.com/tokeninfo";
     9|const TWILIO_API = "https://api.twilio.com/2010-04-01";
    10|const OTP_EXPIRY_MINUTES = 5;
    11|const OTP_MAX_ATTEMPTS = 5;
    12|
    13|interface Env {
    14|  DATABASE_URL: string;
    15|  TWILIO_ACCOUNT_SID: string;
    16|  TWILIO_AUTH_TOKEN: string;
    17|}
    18|
    19|// ─── Helpers ────────────────────────────────────────────────
    20|
    21|function cors(response: Response): Response {
    22|  const headers = new Headers(response.headers);
    23|  headers.set("Access-Control-Allow-Origin", "*");
    24|  headers.set("Access-Control-Allow-Methods", "GET,POST,PUT,PATCH,DELETE,OPTIONS");
    25|  headers.set("Access-Control-Allow-Headers", "Content-Type,Authorization");
    26|  headers.set("Access-Control-Max-Age", "86400");
    27|  return new Response(response.body, { status: response.status, headers });
    28|}
    29|
    30|function json(data: unknown, status = 200): Response {
    31|  return cors(new Response(JSON.stringify(data), {
    32|    status,
    33|    headers: { "Content-Type": "application/json" },
    34|  }));
    35|}
    36|
    37|function extractToken(request: Request): string {
    38|  return (request.headers.get("Authorization") || "").replace("Bearer ", "");
    39|}
    40|
    41|function generateToken(): string {
    42|  return crypto.randomUUID().replace(/-/g, "") + crypto.randomUUID().replace(/-/g, "").slice(0, 16);
    43|}
    44|
    45|function generateOtp(): string {
    46|  return String(Math.floor(100000 + Math.random() * 900000));
    47|}
    48|
    49|// ─── Session Auth ───────────────────────────────────────────
    50|
    51|async function authenticateSession(
    52|  sql: ReturnType<typeof neon>,
    53|  token: string
    54|): Promise<{ profileId: string; userId: string; name: string } | null> {
    55|  if (!token || token.length < 30) return null;
    56|  try {
    57|    const rows = await sql`
    58|      SELECT id, user_id, name FROM ${sql(SCHEMA)}.profiles
    59|      WHERE session_token = ${token} LIMIT 1
    60|    `;
    61|    if (rows.length === 0) return null;
    62|    return { profileId: rows[0].id, userId: rows[0].user_id || "", name: rows[0].name };
    63|  } catch {
    64|    return null;
    65|  }
    66|}
    67|
    68|// ─── Twilio SMS ─────────────────────────────────────────────
    69|
    70|async function sendTwilioSms(
    71|  env: Env,
    72|  to: string,
    73|  body: string
    74|): Promise<boolean> {
    75|  const sid = env.TWILIO_ACCOUNT_SID;
    76|  const token = env.TWILIO_AUTH_TOKEN;
    77|  if (!sid || !token) {
    78|    console.error("Twilio credentials not configured");
    79|    return false;
    80|  }
    81|  try {
    82|    const resp = await fetch(
    83|      `${TWILIO_API}/Accounts/${sid}/Messages.json`,
    84|      {
    85|        method: "POST",
    86|        headers: {
    87|          Authorization: "Basic " + btoa(`${sid}:${token}`),
    88|          "Content-Type": "application/x-www-form-urlencoded",
    89|        },
    90|        body: new URLSearchParams({
    91|          To: to,
    92|          From: "+12562828337", // Will be overridden by Twilio trial/project number
    93|          Body: body,
    94|        }),
    95|      }
    96|    );
    97|    return resp.ok;
    98|  } catch (e) {
    99|    console.error("Twilio send error:", e);
   100|    return false;
   101|  }
   102|}
   103|
   104|// ─── Google Token Verification ──────────────────────────────
   105|
   106|async function verifyGoogleToken(idToken: string): Promise<{
   107|  sub: string; email: string; name: string; picture?: string;
   108|} | null> {
   109|  try {
   110|    const resp = await fetch(`${GOOGLE_TOKENINFO}?id_token=${encodeURIComponent(idToken)}`);
   111|    if (!resp.ok) return null;
   112|    const data = await resp.json() as Record<string, unknown>;
   113|    if (!data.sub || !data.email) return null;
   114|    return {
   115|      sub: data.sub as string,
   116|      email: data.email as string,
   117|      name: (data.name as string) || data.email.split("@")[0],
   118|      picture: data.picture as string | undefined,
   119|    };
   120|  } catch {
   121|    return null;
   122|  }
   123|}
   124|
   125|// ─── Entrypoint ─────────────────────────────────────────────
   126|
   127|export default {
   128|  async fetch(request: Request, env: Env): Promise<Response> {
   129|    if (request.method === "OPTIONS") return cors(new Response(null, { status: 204 }));
   130|
   131|    const url = new URL(request.url);
   132|    const path = url.pathname;
   133|    const dbUrl = env.DATABASE_URL;
   134|
   135|    if (!dbUrl) {
   136|      return json({ error: "DATABASE_URL not configured" }, 500);
   137|    }
   138|
   139|    try {
   140|      const sql = neon(dbUrl);
   141|
   142|      // ── Schema Init (idempotent) ─────────────────────
   143|      try {
   144|        await sql`CREATE SCHEMA IF NOT EXISTS ${sql(SCHEMA)}`;
   145|      } catch { /* schema may already exist */ }
   146|
   147|      try {
   148|        await sql`
   149|          CREATE TABLE IF NOT EXISTS ${sql(SCHEMA)}.profiles (
   150|            id TEXT PRIMARY KEY,
   151|            user_id TEXT,
   152|            phone TEXT,
   153|            name TEXT NOT NULL DEFAULT '',
   154|            email TEXT,
   155|            session_token TEXT,
   156|            auth_provider TEXT,
   157|            onboarding_complete BOOLEAN DEFAULT false,
   158|            is_logged_in BOOLEAN DEFAULT false,
   159|            dark_theme BOOLEAN DEFAULT false,
   160|            locale_code TEXT DEFAULT 'en',
   161|            family_code TEXT DEFAULT '',
   162|            notifications_enabled BOOLEAN DEFAULT true,
   163|            camp_reminders_enabled BOOLEAN DEFAULT true,
   164|            consent_accepted BOOLEAN DEFAULT false,
   165|            consent_declined BOOLEAN DEFAULT false
   166|          )
   167|        `;
   168|      } catch { /* table may already exist */ }
   169|
   170|      try {
   171|        await sql`
   172|          CREATE TABLE IF NOT EXISTS ${sql(SCHEMA)}.phone_otps (
   173|            phone TEXT PRIMARY KEY,
   174|            otp TEXT NOT NULL,
   175|            expires_at TIMESTAMPTZ NOT NULL,
   176|            attempts INT DEFAULT 0
   177|          )
   178|        `;
   179|      } catch { /* table may already exist */ }
   180|
   181|      // ── Health Check ─────────────────────────────────
   182|      if (path === "/ping") {
   183|        const rows = await sql`SELECT 1 AS ok, NOW() AS now`;
   184|        return json({ ok: true, db: rows[0] });
   185|      }
   186|
   187|      // ═══════════════════════════════════════════════════
   188|      // AUTH ENDPOINTS
   189|      // ═══════════════════════════════════════════════════
   190|
   191|      // ── Google Sign-In ────────────────────────────────
   192|      if (path === "/api/auth/google" && request.method === "POST") {
   193|        const body: Record<string, unknown> = await request.json();
   194|        const idToken = body.id_token as string;
   195|        if (!idToken) return json({ error: "Missing id_token" }, 400);
   196|
   197|        const googleUser = await verifyGoogleToken(idToken);
   198|        if (!googleUser) return json({ error: "Invalid Google ID token" }, 401);
   199|
   200|        const profileId = `g_${googleUser.sub.slice(0, 24)}`;
   201|        const sessionToken = generateToken();
   202|
   203|        // Upsert profile for this Google user
   204|        const existing = await sql`
   205|          SELECT id FROM ${sql(SCHEMA)}.profiles WHERE id = ${profileId} LIMIT 1
   206|        `;
   207|
   208|        if (existing.length === 0) {
   209|          await sql`
   210|            INSERT INTO ${sql(SCHEMA)}.profiles
   211|              (id, user_id, name, email, session_token, auth_provider,
   212|               onboarding_complete, is_logged_in)
   213|            VALUES (
   214|              ${profileId}, ${googleUser.sub}, ${googleUser.name},
   215|              ${googleUser.email}, ${sessionToken}, 'GOOGLE', true, true
   216|            )
   217|          `;
   218|        } else {
   219|          await sql`
   220|            UPDATE ${sql(SCHEMA)}.profiles
   221|            SET session_token = ${sessionToken}, is_logged_in = true,
   222|                name = ${googleUser.name}, email = ${googleUser.email}
   223|            WHERE id = ${profileId}
   224|          `;
   225|        }
   226|
   227|        return json({
   228|          token: sessionToken,
   229|          profile: {
   230|            id: profileId,
   231|            user_id: googleUser.sub,
   232|            name: googleUser.name,
   233|            email: googleUser.email,
   234|            auth_provider: "GOOGLE",
   235|          },
   236|        });
   237|      }
   238|
   239|      // ── Phone OTP: Send ──────────────────────────────
   240|      if (path === "/api/auth/phone/send" && request.method === "POST") {
   241|        const body: Record<string, unknown> = await request.json();
   242|        const phone = (body.phone as string)?.trim();
   243|        if (!phone) return json({ error: "Missing phone" }, 400);
   244|
   245|        const otp = generateOtp();
   246|        const expiresAt = new Date(Date.now() + OTP_EXPIRY_MINUTES * 60_000);
   247|
   248|        await sql`
   249|          INSERT INTO ${sql(SCHEMA)}.phone_otps (phone, otp, expires_at, attempts)
   250|          VALUES (${phone}, ${otp}, ${expiresAt.toISOString()}, 0)
   251|          ON CONFLICT (phone) DO UPDATE SET
   252|            otp = EXCLUDED.otp,
   253|            expires_at = EXCLUDED.expires_at,
   254|            attempts = 0
   255|        `;
   256|
   257|        const sent = await sendTwilioSms(
   258|          env, phone,
   259|          `Your VitaHero verification code is: ${otp}`
   260|        );
   261|
   262|        return json({ success: sent, note: sent ? undefined : "OTP generated but SMS delivery may be delayed" });
   263|      }
   264|
   265|      // ── Phone OTP: Verify ────────────────────────────
   266|      if (path === "/api/auth/phone/verify" && request.method === "POST") {
   267|        const body: Record<string, unknown> = await request.json();
   268|        const phone = (body.phone as string)?.trim();
   269|        const otp = (body.otp as string)?.trim();
   270|        if (!phone || !otp) return json({ error: "Missing phone or otp" }, 400);
   271|
   272|        const rows = await sql`
   273|          SELECT otp, expires_at, attempts
   274|          FROM ${sql(SCHEMA)}.phone_otps WHERE phone = ${phone} LIMIT 1
   275|        `;
   276|
   277|        if (rows.length === 0) {
   278|          return json({ error: "No OTP requested for this number" }, 400);
   279|        }
   280|
   281|        const record = rows[0];
   282|        if (record.attempts >= OTP_MAX_ATTEMPTS) {
   283|          return json({ error: "Too many attempts. Request a new OTP." }, 429);
   284|        }
   285|        if (new Date(record.expires_at) < new Date()) {
   286|          return json({ error: "OTP expired. Request a new one." }, 410);
   287|        }
   288|
   289|        // Increment attempts
   290|        await sql`
   291|          UPDATE ${sql(SCHEMA)}.phone_otps
   292|          SET attempts = attempts + 1 WHERE phone = ${phone}
   293|        `;
   294|
   295|        if (record.otp !== otp) {
   296|          return json({ error: "Invalid OTP" }, 401);
   297|        }
   298|
   299|        // OTP verified — clean up
   300|        await sql`DELETE FROM ${sql(SCHEMA)}.phone_otps WHERE phone = ${phone}`;
   301|
   302|        // Create or update profile
   303|        const profileId = `ph_${phone.replace(/\D/g, "").slice(-10)}`;
   304|        const sessionToken = generateToken();
   305|
   306|        const existing = await sql`
   307|          SELECT id FROM ${sql(SCHEMA)}.profiles WHERE id = ${profileId} LIMIT 1
   308|        `;
   309|
   310|        if (existing.length === 0) {
   311|          await sql`
   312|            INSERT INTO ${sql(SCHEMA)}.profiles
   313|              (id, phone, name, session_token, auth_provider,
   314|               onboarding_complete, is_logged_in)
   315|            VALUES (
   316|              ${profileId}, ${phone}, 'Parent', ${sessionToken}, 'PHONE',
   317|              true, true
   318|            )
   319|          `;
   320|        } else {
   321|          await sql`
   322|            UPDATE ${sql(SCHEMA)}.profiles
   323|            SET session_token = ${sessionToken}, is_logged_in = true, phone = ${phone}
   324|            WHERE id = ${profileId}
   325|          `;
   326|        }
   327|
   328|        // Also delete any old OTPs
   329|        try {
   330|          await sql`DELETE FROM ${sql(SCHEMA)}.phone_otps WHERE expires_at < NOW()`;
   331|        } catch { /* best effort */ }
   332|
   333|        return json({
   334|          token: sessionToken,
   335|          profile: {
   336|            id: profileId,
   337|            phone,
   338|            name: "Parent",
   339|            auth_provider: "PHONE",
   340|          },
   341|        });
   342|      }
   343|
   344|      // ── Verify Session Token ─────────────────────────
   345|      if (path === "/api/auth/me" && request.method === "GET") {
   346|        const token = extractToken(request);
   347|        const session = await authenticateSession(sql, token);
   348|        if (!session) return json({ error: "Invalid or expired session" }, 401);
   349|
   350|        const profile = await sql`
   351|          SELECT * FROM ${sql(SCHEMA)}.profiles WHERE id = ${session.profileId} LIMIT 1
   352|        `;
   353|        return json(profile[0] || null);
   354|      }
   355|
   356|      // ── Logout ───────────────────────────────────────
   357|      if (path === "/api/auth/logout" && request.method === "POST") {
   358|        const token = extractToken(request);
   359|        if (token) {
   360|          await sql`
   361|            UPDATE ${sql(SCHEMA)}.profiles
   362|            SET session_token = NULL, is_logged_in = false
   363|            WHERE session_token = ${token}
   364|          `;
   365|        }
   366|        return json({ success: true });
   367|      }
   368|
   369|      // ═══════════════════════════════════════════════════
   370|      // AUTHENTICATED DATA ENDPOINTS
   371|      // ═══════════════════════════════════════════════════
   372|
   373|      const token = extractToken(request);
   374|      const session = await authenticateSession(sql, token);
   375|
   376|      // ═══════════════════════════════════════════════════
   377|      // Profiles
   378|      // ═══════════════════════════════════════════════════
   379|
   380|      if (path === "/api/profiles" && request.method === "GET") {
   381|        if (!session) return json({ error: "Unauthorized" }, 401);
   382|        const rows = await sql`SELECT * FROM ${sql(SCHEMA)}.profiles WHERE id = ${session.profileId} LIMIT 1`;
   383|        // Don't leak session token
   384|        if (rows[0]) delete rows[0].session_token;
   385|        return json(rows[0] || null);
   386|      }
   387|
   388|      if (path === "/api/profiles" && request.method === "POST") {
   389|        if (!session) return json({ error: "Unauthorized" }, 401);
   390|        const body: Record<string, unknown> = await request.json();
   391|        const row = await sql`
   392|          INSERT INTO ${sql(SCHEMA)}.profiles
   393|            (id, user_id, phone, name, email,
   394|             onboarding_complete, is_logged_in,
   395|             dark_theme, locale_code, family_code,
   396|             notifications_enabled, camp_reminders_enabled,
   397|             consent_accepted, consent_declined,
   398|             auth_provider, session_token)
   399|          VALUES (
   400|            ${session.profileId},
   401|            ${(body.user_id as string) || session.userId},
   402|            ${(body.phone as string) || null},
   403|            ${(body.name as string) || session.name},
   404|            ${(body.email as string) || null},
   405|            ${(body.onboarding_complete as boolean) || false},
   406|            ${(body.is_logged_in as boolean) || false},
   407|            ${(body.dark_theme as boolean) || false},
   408|            ${(body.locale_code as string) || "en"},
   409|            ${(body.family_code as string) || ""},
   410|            ${(body.notifications_enabled as boolean) ?? true},
   411|            ${(body.camp_reminders_enabled as boolean) ?? true},
   412|            ${(body.consent_accepted as boolean) || false},
   413|            ${(body.consent_declined as boolean) || false},
   414|            ${(body.auth_provider as string) || "GOOGLE"},
   415|            ${token}
   416|          )
   417|          ON CONFLICT (id) DO UPDATE SET
   418|            user_id = EXCLUDED.user_id, phone = EXCLUDED.phone,
   419|            name = EXCLUDED.name, email = EXCLUDED.email,
   420|            onboarding_complete = EXCLUDED.onboarding_complete,
   421|            is_logged_in = EXCLUDED.is_logged_in,
   422|            dark_theme = EXCLUDED.dark_theme,
   423|            locale_code = EXCLUDED.locale_code,
   424|            family_code = EXCLUDED.family_code,
   425|            notifications_enabled = EXCLUDED.notifications_enabled,
   426|            camp_reminders_enabled = EXCLUDED.camp_reminders_enabled,
   427|            consent_accepted = EXCLUDED.consent_accepted,
   428|            consent_declined = EXCLUDED.consent_declined,
   429|            auth_provider = EXCLUDED.auth_provider
   430|          RETURNING *
   431|        `;
   432|        if (row[0]) delete row[0].session_token;
   433|        return json(row[0], 201);
   434|      }
   435|
   436|      // ═══════════════════════════════════════════════════
   437|      // Kids
   438|      // ═══════════════════════════════════════════════════
   439|
   440|      if (path === "/api/kids" && request.method === "GET") {
   441|        if (!session) return json({ error: "Unauthorized" }, 401);
   442|        const profileId = session.profileId;
   443|        const rows = await sql`SELECT * FROM ${sql(SCHEMA)}.kids WHERE profile_id = ${profileId} ORDER BY name`;
   444|        return json(rows);
   445|      }
   446|
   447|      if (path === "/api/kids" && request.method === "POST") {
   448|        if (!session) return json({ error: "Unauthorized" }, 401);
   449|        const body: Record<string, unknown> = await request.json();
   450|        const row = await sql`
   451|          INSERT INTO ${sql(SCHEMA)}.kids
   452|            (id, profile_id, user_id, name, age, gender, school, grade,
   453|             height_cm, weight_kg, avatar_color, overall_score, dental,
   454|             eyesight, nutrition, last_checkup)
   455|          VALUES (
   456|            ${body.id as string}, ${session.profileId},
   457|            ${session.userId || null}, ${body.name as string},
   458|            ${body.age as number}, ${body.gender as string},
   459|            ${(body.school as string) || ""}, ${(body.grade as string) || ""},
   460|            ${(body.height_cm as number) || 0}, ${(body.weight_kg as number) || 0},
   461|            ${(body.avatar_color as number) || 0}, ${(body.overall_score as number) || 80},
   462|            ${(body.dental as string) || "GOOD"}, ${(body.eyesight as string) || "GOOD"},
   463|            ${(body.nutrition as string) || "GOOD"}, ${(body.last_checkup as string) || "Not yet"}
   464|          )
   465|          ON CONFLICT (id) DO UPDATE SET
   466|            profile_id = EXCLUDED.profile_id, user_id = EXCLUDED.user_id,
   467|            name = EXCLUDED.name, age = EXCLUDED.age, gender = EXCLUDED.gender,
   468|            school = EXCLUDED.school, grade = EXCLUDED.grade,
   469|            height_cm = EXCLUDED.height_cm, weight_kg = EXCLUDED.weight_kg,
   470|            avatar_color = EXCLUDED.avatar_color, overall_score = EXCLUDED.overall_score,
   471|            dental = EXCLUDED.dental, eyesight = EXCLUDED.eyesight,
   472|            nutrition = EXCLUDED.nutrition, last_checkup = EXCLUDED.last_checkup
   473|          RETURNING *
   474|        `;
   475|        return json(row[0], 201);
   476|      }
   477|
   478|      if (path.startsWith("/api/kids/") && request.method === "DELETE") {
   479|        if (!session) return json({ error: "Unauthorized" }, 401);
   480|        const kidId = path.split("/")[3];
   481|        await sql`DELETE FROM ${sql(SCHEMA)}.kids WHERE id = ${kidId} AND profile_id = ${session.profileId}`;
   482|        return json({ deleted: true });
   483|      }
   484|
   485|      // ═══════════════════════════════════════════════════
   486|      // Appointments
   487|      // ═══════════════════════════════════════════════════
   488|
   489|      if (path === "/api/appointments" && request.method === "GET") {
   490|        if (!session) return json({ error: "Unauthorized" }, 401);
   491|        const rows = await sql`SELECT * FROM ${sql(SCHEMA)}.appointments WHERE profile_id = ${session.profileId} ORDER BY date, time`;
   492|        return json(rows);
   493|      }
   494|
   495|      if (path === "/api/appointments" && request.method === "POST") {
   496|        if (!session) return json({ error: "Unauthorized" }, 401);
   497|        const body: Record<string, unknown> = await request.json();
   498|        const row = await sql`
   499|          INSERT INTO ${sql(SCHEMA)}.appointments
   500|            (id, profile_id, user_id, doctor_name, specialty, kid_name, date, time)
   501|          VALUES (
   502|            ${body.id as string}, ${session.profileId},
   503|            ${session.userId || null}, ${body.doctor_name as string},
   504|            ${body.specialty as string}, ${body.kid_name as string},
   505|            ${body.date as string}, ${body.time as string}
   506|          )
   507|          ON CONFLICT (id) DO UPDATE SET
   508|            profile_id = EXCLUDED.profile_id, user_id = EXCLUDED.user_id,
   509|            doctor_name = EXCLUDED.doctor_name, specialty = EXCLUDED.specialty,
   510|            kid_name = EXCLUDED.kid_name, date = EXCLUDED.date, time = EXCLUDED.time
   511|          RETURNING *
   512|        `;
   513|        return json(row[0], 201);
   514|      }
   515|
   516|      if (path.startsWith("/api/appointments/") && request.method === "DELETE") {
   517|        if (!session) return json({ error: "Unauthorized" }, 401);
   518|        const apptId = path.split("/")[3];
   519|        await sql`DELETE FROM ${sql(SCHEMA)}.appointments WHERE id = ${apptId} AND profile_id = ${session.profileId}`;
   520|        return json({ deleted: true });
   521|      }
   522|
   523|      // ═══════════════════════════════════════════════════
   524|      // Camps
   525|      // ═══════════════════════════════════════════════════
   526|
   527|      if (path === "/api/camps" && request.method === "GET") {
   528|        if (!session) return json({ error: "Unauthorized" }, 401);
   529|        const rows = await sql`SELECT * FROM ${sql(SCHEMA)}.camps WHERE profile_id = ${session.profileId} ORDER BY date`;
   530|        return json(rows);
   531|      }
   532|
